-- Marketing fact table and source-owned field projection.
CREATE TABLE IF NOT EXISTS live_ad_hourly (
 route_id VARCHAR(128) NOT NULL,
 stat_hour DATETIME NOT NULL,
 dimension_hash CHAR(64) CHARACTER SET ascii NOT NULL,
 product_id VARCHAR(128) NOT NULL,
 room_id VARCHAR(128) NOT NULL,
 source VARCHAR(16) NOT NULL,
 account_id VARCHAR(128) NOT NULL,
 stat_cost DECIMAL(24,6) NULL,
 dimensions JSON NOT NULL,
 metrics JSON NOT NULL,
 observed_at DATETIME NOT NULL,
 PRIMARY KEY(route_id, stat_hour, dimension_hash),
 INDEX idx_ad_room_hour (room_id, stat_hour)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE OR REPLACE VIEW v_marketing_hourly AS
SELECT
  route_id,
  product_id,
  room_id,
  source,
  account_id,
  stat_hour,
  observed_at,
  dimensions AS raw_dimensions,
  metrics AS raw_metrics,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(dimensions, '$."stat_time_hour"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(dimensions, '$."stat_time_hour"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(dimensions, '$."stat_time_hour"')) ELSE NULL END AS `stat_time_hour`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_day"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_day"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_day"')) ELSE NULL END AS `stat_time_day`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_month"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_month"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_month"')) ELSE NULL END AS `stat_time_month`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."advertiser_id"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."advertiser_id"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."advertiser_id"')) ELSE NULL END AS `advertiser_id`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_name"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_name"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_name"')) ELSE NULL END AS `account_name`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_type"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_type"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_type"')) ELSE NULL END AS `account_type`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_platform"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_platform"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_platform"')) ELSE NULL END AS `stat_platform`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."stat_cost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."stat_cost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."stat_cost"')) AS DECIMAL(65,30)) ELSE NULL END AS `stat_cost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."show_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."show_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."show_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `show_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."cpm_platform"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cpm_platform"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cpm_platform"')) AS DECIMAL(65,30)) ELSE NULL END AS `cpm_platform`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."click_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."click_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."click_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `click_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."ctr"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."ctr"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."ctr"')) AS DECIMAL(65,30)) ELSE NULL END AS `ctr`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."cpc_platform"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cpc_platform"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cpc_platform"')) AS DECIMAL(65,30)) ELSE NULL END AS `cpc_platform`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."attribution_convert_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_convert_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_convert_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `attribution_convert_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."attribution_convert_cost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_convert_cost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_convert_cost"')) AS DECIMAL(65,30)) ELSE NULL END AS `attribution_convert_cost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."attribution_conversion_rate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_conversion_rate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_conversion_rate"')) AS DECIMAL(65,30)) ELSE NULL END AS `attribution_conversion_rate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."convert_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."convert_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."convert_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `convert_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."conversion_cost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."conversion_cost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."conversion_cost"')) AS DECIMAL(65,30)) ELSE NULL END AS `conversion_cost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."conversion_rate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."conversion_rate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."conversion_rate"')) AS DECIMAL(65,30)) ELSE NULL END AS `conversion_rate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."form"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."form"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."form"')) AS DECIMAL(65,30)) ELSE NULL END AS `form`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."form_submit"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."form_submit"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."form_submit"')) AS DECIMAL(65,30)) ELSE NULL END AS `form_submit`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."consult_effective"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."consult_effective"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."consult_effective"')) AS DECIMAL(65,30)) ELSE NULL END AS `consult_effective`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."attribution_form"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_form"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_form"')) AS DECIMAL(65,30)) ELSE NULL END AS `attribution_form`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."form_and_submit_count"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."form_and_submit_count"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."form_and_submit_count"')) AS DECIMAL(65,30)) ELSE NULL END AS `form_and_submit_count`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."form_and_submit_cost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."form_and_submit_cost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."form_and_submit_cost"')) AS DECIMAL(65,30)) ELSE NULL END AS `form_and_submit_cost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."premium_payment_count"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."premium_payment_count"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."premium_payment_count"')) AS DECIMAL(65,30)) ELSE NULL END AS `premium_payment_count`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."premium_payment_cost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."premium_payment_cost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."premium_payment_cost"')) AS DECIMAL(65,30)) ELSE NULL END AS `premium_payment_cost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."stat_insurance_payment_pay_amount"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."stat_insurance_payment_pay_amount"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."stat_insurance_payment_pay_amount"')) AS DECIMAL(65,30)) ELSE NULL END AS `stat_insurance_payment_pay_amount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."stat_insurance_payment_roi"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."stat_insurance_payment_roi"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."stat_insurance_payment_roi"')) AS DECIMAL(65,30)) ELSE NULL END AS `stat_insurance_payment_roi`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."attribution_insurance_payment_pay_amount"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_insurance_payment_pay_amount"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_insurance_payment_pay_amount"')) AS DECIMAL(65,30)) ELSE NULL END AS `attribution_insurance_payment_pay_amount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."attribution_insurance_payment_roi"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_insurance_payment_roi"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."attribution_insurance_payment_roi"')) AS DECIMAL(65,30)) ELSE NULL END AS `attribution_insurance_payment_roi`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."luban_live_enter_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."luban_live_enter_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."luban_live_enter_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `luban_live_enter_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."live_watch_one_minute_count"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."live_watch_one_minute_count"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."live_watch_one_minute_count"')) AS DECIMAL(65,30)) ELSE NULL END AS `live_watch_one_minute_count`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."luban_live_follow_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."luban_live_follow_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."luban_live_follow_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `luban_live_follow_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."luban_live_share_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."luban_live_share_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."luban_live_share_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `luban_live_share_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."luban_live_comment_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."luban_live_comment_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."luban_live_comment_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `luban_live_comment_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."live_component_click_count"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."live_component_click_count"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."live_component_click_count"')) AS DECIMAL(65,30)) ELSE NULL END AS `live_component_click_count`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."live_component_click_cost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."live_component_click_cost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."live_component_click_cost"')) AS DECIMAL(65,30)) ELSE NULL END AS `live_component_click_cost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."live_component_click_rate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."live_component_click_rate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."live_component_click_rate"')) AS DECIMAL(65,30)) ELSE NULL END AS `live_component_click_rate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."deep_convert_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."deep_convert_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."deep_convert_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `deep_convert_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."deep_convert_cost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."deep_convert_cost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."deep_convert_cost"')) AS DECIMAL(65,30)) ELSE NULL END AS `deep_convert_cost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."deep_convert_rate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."deep_convert_rate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."deep_convert_rate"')) AS DECIMAL(65,30)) ELSE NULL END AS `deep_convert_rate`
FROM live_ad_hourly WHERE source = 'marketing';
